# hashing produces a repeatable identifier for the inputs used to generate coaching.
import hashlib
import json
from pathlib import Path

# changing the cache version invalidates results generated by an older coaching format.
CACHE_VERSION = "phase07-coaching-v1"

def create_coaching_fingerprint(
    metrics: dict,
    model_name: str,
) -> str:
    """create a stable fingerprint for coaching inputs."""

    # include the model and metrics so different inputs do not reuse outdated feedback.
    payload = {
        "cache_version": CACHE_VERSION,
        "model": model_name,
        "metrics": metrics,
    }

    # normalize json ordering and formatting before computing the fingerprint.
    serialized = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )

    return hashlib.sha256(
        serialized.encode("utf-8")
    ).hexdigest()


def load_cached_coaching(
    cache_path: Path,
    fingerprint: str,
) -> dict | None:
    """return cached coaching if its fingerprint matches."""

    # a missing cache is treated as a miss rather than an error.
    if not cache_path.is_file():
        return None

    try:
        with cache_path.open("r", encoding="utf-8") as file:
            cached = json.load(file)

        # only reuse coaching when its stored input fingerprint matches.
        if cached.get("fingerprint") != fingerprint:
            return None

        coaching = cached.get("coaching")

        # reject malformed cache entries instead of returning invalid feedback.
        if not isinstance(coaching, dict):
            return None

        return coaching

    # unreadable or invalid cache data falls back to generating fresh feedback.
    except (OSError, ValueError, TypeError):
        return None


def save_cached_coaching(
    cache_path: Path,
    fingerprint: str,
    coaching: dict,
) -> None:
    """save coaching atomically to avoid partial json files."""

    # create the output directory before writing a cache entry.
    cache_path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    # write to a temporary file first to avoid leaving a partially written cache.
    temp_path = cache_path.with_name(
        cache_path.name + ".tmp"
    )

    # include the model and metrics so different inputs do not reuse outdated feedback.
    payload = {
        "fingerprint": fingerprint,
        "coaching": coaching,
    }

    with temp_path.open("w", encoding="utf-8") as file:
        json.dump(payload, file, indent=2)

    # replace the target file after the temporary write completes.
    temp_path.replace(cache_path)
